describe('Notification Panel Slide-in from Top', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should display notification panel sliding in from top on page load', () => {
    // Verify notification panel is visible
    cy.get('[data-testid="notification-panel"]').should('be.visible');

    // Verify panel has correct initial position (off-screen or top-aligned)
    cy.get('[data-testid="notification-panel"]').should('have.css', 'transform', 'translateY(0px)');

    // Verify panel contains expected content
    cy.get('[data-testid="notification-panel"]').should('contain', 'New message received');
    cy.get('[data-testid="notification-panel"]').should('contain', 'You have 3 unread notifications');

    // Verify panel has close button
    cy.get('[data-testid="close-notification-button"]').should('be.visible');

    // Verify panel is positioned at the top of the viewport
    cy.get('[data-testid="notification-panel"]').should('have.css', 'top', '0px');
  });

  it('should hide notification panel when close button is clicked', () => {
    // Verify panel is visible before interaction
    cy.get('[data-testid="notification-panel"]').should('be.visible');

    // Click the close button
    cy.get('[data-testid="close-notification-button"]').click();

    // Verify panel is no longer visible
    cy.get('[data-testid="notification-panel"]').should('not.exist');

    // Verify panel is removed from DOM or hidden
    cy.get('[data-testid="notification-panel"]').should('have.css', 'display', 'none');

    // Verify close button is no longer visible
    cy.get('[data-testid="close-notification-button"]').should('not.exist');

    // Verify panel is not in viewport
    cy.get('[data-testid="notification-panel"]').should('not.be.visible');
  });
});
